#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>
#import <objc/runtime.h>
#import <objc/message.h>

static NSString *PPath(void){ return [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/XTabBarCapacityProbe.log"]; }
static void PLog(NSString *fmt, ...){ va_list ap; va_start(ap,fmt); NSString *s=[[NSString alloc] initWithFormat:fmt arguments:ap]; va_end(ap); NSString *line=[NSString stringWithFormat:@"[%@] %@\n",[NSDate date],s]; NSFileHandle *h=[NSFileHandle fileHandleForWritingAtPath:PPath()]; if(!h){ [@"" writeToFile:PPath() atomically:YES encoding:NSUTF8StringEncoding error:nil]; h=[NSFileHandle fileHandleForWritingAtPath:PPath()]; } [h seekToEndOfFile]; [h writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile]; NSLog(@"[XTabBarCapacityProbe] %@",s); }

static void DumpClass(NSString *name){ Class c=NSClassFromString(name); PLog(@"RUNTIME_CLASS_BEGIN class=%@ present=%@ ptr=%p",name,c?@"YES":@"NO",c); if(!c)return; unsigned n=0; Method *ms=class_copyMethodList(c,&n); for(unsigned i=0;i<n;i++) PLog(@"METHOD class=%@ selector=%s encoding=%s imp=%p",name,sel_getName(method_getName(ms[i])),method_getTypeEncoding(ms[i]),method_getImplementation(ms[i])); free(ms); Class meta=object_getClass(c); ms=class_copyMethodList(meta,&n); for(unsigned i=0;i<n;i++) PLog(@"CLASS_METHOD class=%@ selector=%s encoding=%s imp=%p",name,sel_getName(method_getName(ms[i])),method_getTypeEncoding(ms[i]),method_getImplementation(ms[i])); free(ms); PLog(@"RUNTIME_CLASS_END class=%@",name); }

static void DumpMatchingClasses(void){ int count=objc_getClassList(NULL,0); Class *classes=malloc(sizeof(Class)*count); count=objc_getClassList(classes,count); NSMutableArray *hits=[NSMutableArray array]; NSArray *needles=@[@"TabBar",@"TabCustomization",@"TabDataSource",@"NavigationSettings",@"BottomTab",@"Toast"]; for(int i=0;i<count;i++){ NSString *n=NSStringFromClass(classes[i]); for(NSString *x in needles) if([n rangeOfString:x options:NSCaseInsensitiveSearch].location!=NSNotFound){ [hits addObject:n]; break; } } free(classes); [hits sortUsingSelector:@selector(compare:)]; PLog(@"SURFACE_SUMMARY count=%lu classes=%@",(unsigned long)hits.count,hits); }

static void DumpUI(void){ dispatch_async(dispatch_get_main_queue(), ^{ UIWindow *w=nil; for(UIScene *s in UIApplication.sharedApplication.connectedScenes) if([s isKindOfClass:UIWindowScene.class]) for(UIWindow *x in ((UIWindowScene*)s).windows) if(x.isKeyWindow){w=x;break;} PLog(@"SNAPSHOT keyWindow=%p root=%@",w,NSStringFromClass(w.rootViewController.class)); NSMutableArray *q=[NSMutableArray arrayWithObject:w?:[NSNull null]]; NSUInteger seen=0; while(q.count && seen<300){ id o=q.firstObject; [q removeObjectAtIndex:0]; if(o==[NSNull null])continue; if([o isKindOfClass:UIView.class]){ UIView *v=o; NSString *cn=NSStringFromClass(v.class); if([cn rangeOfString:@"Tab" options:NSCaseInsensitiveSearch].location!=NSNotFound || [cn rangeOfString:@"Toast" options:NSCaseInsensitiveSearch].location!=NSNotFound) PLog(@"VIEW class=%@ ptr=%p frame=%@ hidden=%d subviews=%lu",cn,v,NSStringFromCGRect(v.frame),v.hidden,(unsigned long)v.subviews.count); [q addObjectsFromArray:v.subviews]; seen++; } } }); }

static void InstallObserver(void){ [[NSNotificationCenter defaultCenter] addObserverForName:UIWindowDidBecomeKeyNotification object:nil queue:NSOperationQueue.mainQueue usingBlock:^(__unused NSNotification *n){ DumpUI(); }]; }

__attribute__((constructor)) static void ProbeInit(void){ @autoreleasepool { PLog(@"BOOT version=1.0 mode=PASSIVE path=%@",PPath()); PLog(@"STATE appVersion=%@ build=%@",[[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"],[[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleVersion"]); NSArray *targets=@[@"T1BottomTabBarItemCapacity",@"MainAppNavigationSettings",@"MainAppTabDataSource",@"TabCustomizationConfig",@"TabCustomizationViewModel",@"TabCustomizationGridViewController",@"TabCustomizationSelectedItemsViewController",@"TabCustomizationToastViewModel",@"XNavigation.TabBarController",@"XNavigation.TabBarView",@"XNavigation.TabBarItemView",@"T1TabBarViewController",@"XTabbedAppNavigationViewController"]; for(NSString *n in targets) DumpClass(n); DumpMatchingClasses(); InstallObserver(); dispatch_after(dispatch_time(DISPATCH_TIME_NOW,3*NSEC_PER_SEC),dispatch_get_main_queue(),^{ DumpUI(); }); PLog(@"INSTALL passive runtime/UI observation ready; no return values modified"); } }
